create or replace function public.complete_production(p_production_batch_id uuid,p_consumptions jsonb,p_outputs jsonb) returns jsonb language plpgsql security invoker set search_path = '' as $$ declare v_user uuid:=auth.uid();r record;b record;v_need numeric;v_take numeric;v_batch_id uuid;v_total numeric:=0;v_status text;v_approval text;begin if v_user is null then raise exception 'Authentication required';end if;select status,wife_approval_status into v_status,v_approval from public.production_batches where id=p_production_batch_id for update;if v_status is null then raise exception 'Production batch not found';end if;if v_status='completed' then raise exception 'Production batch already completed';end if;if v_approval<>'approved' then raise exception 'Production batch not approved';end if;for r in select * from jsonb_to_recordset(p_consumptions) as x(ingredient_item_id uuid,actual_quantity numeric,unit_id uuid) loop v_need:=r.actual_quantity;if v_need<=0 then continue;end if;for b in select id,quantity_remaining,unit_id,unit_cost from public.inventory_batches where item_id=r.ingredient_item_id and status='active' and quantity_remaining>0 order by batch_date,created_at,id for update loop exit when v_need<=0;if b.unit_id<>r.unit_id then raise exception 'Unit mismatch for ingredient %',r.ingredient_item_id;end if;v_take:=least(v_need,b.quantity_remaining);update public.inventory_batches set quantity_remaining=quantity_remaining-v_take,status=case when quantity_remaining-v_take<=0 then 'depleted' else status end,updated_at=now() where id=b.id;insert into public.inventory_transactions(item_id,batch_id,transaction_type,quantity,unit_id,occurred_at,reference_type,reference_id,unit_cost,notes,created_by) values(r.ingredient_item_id,b.id,'production_consumption',-v_take,r.unit_id,now(),'production_batch',p_production_batch_id,b.unit_cost,'Production consumption',v_user);insert into public.production_consumption(production_batch_id,ingredient_item_id,planned_quantity,actual_quantity,unit_id,batch_id,consumption_date,one_time_variance,recipe_change_requested) values(p_production_batch_id,r.ingredient_item_id,null,v_take,r.unit_id,b.id,current_date,false,false);v_need:=v_need-v_take;v_total:=v_total+v_take;end loop;if v_need>0 then raise exception 'Insufficient stock for ingredient %; short by %',r.ingredient_item_id,v_need;end if;end loop;for r in select * from jsonb_to_recordset(p_outputs) as x(output_item_id uuid,quantity numeric,unit_id uuid,unit_cost numeric) loop if r.quantity<=0 then continue;end if;v_batch_id:=gen_random_uuid();insert into public.inventory_batches(id,item_id,source_type,source_id,source_line_id,batch_date,quantity_received,quantity_remaining,unit_id,unit_cost,status) values(v_batch_id,r.output_item_id,'production',p_production_batch_id,null,current_date,r.quantity,r.quantity,r.unit_id,r.unit_cost,'active');insert into public.production_outputs(production_batch_id,output_item_id,quantity,unit_id,output_date,batch_id) values(p_production_batch_id,r.output_item_id,r.quantity,r.unit_id,current_date,v_batch_id);insert into public.inventory_transactions(item_id,batch_id,transaction_type,quantity,unit_id,occurred_at,reference_type,reference_id,unit_cost,notes,created_by) values(r.output_item_id,v_batch_id,'production_output',r.quantity,r.unit_id,now(),'production_batch',p_production_batch_id,r.unit_cost,'Production output',v_user);end loop;update public.production_batches set status='completed',actual_output_quantity=coalesce((select sum(quantity) from public.production_outputs where production_batch_id=p_production_batch_id),0),updated_at=now() where id=p_production_batch_id;perform public.record_audit_event('production.completed','production_batch',p_production_batch_id,jsonb_build_object('consumed',v_total),'application');return jsonb_build_object('production_batch_id',p_production_batch_id,'status','completed');end; $$;
revoke all on function public.complete_production(uuid,jsonb,jsonb) from public,anon;grant execute on function public.complete_production(uuid,jsonb,jsonb) to authenticated;

create or replace function public.dispatch_order(p_order_id uuid,p_dispatch_date date,p_method text,p_lines jsonb) returns jsonb language plpgsql security invoker set search_path = '' as $$ declare v_user uuid:=auth.uid();v_dispatch_id uuid:=gen_random_uuid();r record;b record;v_need numeric;v_take numeric;v_line_id uuid;v_order_status text;begin if v_user is null then raise exception 'Authentication required';end if;select status into v_order_status from public.orders where id=p_order_id for update;if v_order_status is null then raise exception 'Order not found';end if;if v_order_status not in ('confirmed','production_planned','ready','partially_dispatched') then raise exception 'Order is not ready for dispatch';end if;insert into public.dispatches(id,order_id,dispatch_date,dispatch_method,status,created_by) values(v_dispatch_id,p_order_id,p_dispatch_date,p_method,'dispatched',v_user);for r in select * from jsonb_to_recordset(p_lines) as x(order_line_id uuid,quantity numeric) loop v_need:=r.quantity;if v_need<=0 then continue;end if;for b in select ib.id,ib.item_id,ib.quantity_remaining,ib.unit_id,ib.unit_cost from public.inventory_batches ib where ib.item_id=(select item_id from public.order_lines where id=r.order_line_id and order_id=p_order_id) and ib.status='active' and ib.quantity_remaining>0 order by ib.batch_date,ib.created_at,ib.id for update loop exit when v_need<=0;v_take:=least(v_need,b.quantity_remaining);v_line_id:=gen_random_uuid();insert into public.dispatch_lines(id,dispatch_id,order_line_id,item_id,quantity,unit_id,batch_id) values(v_line_id,v_dispatch_id,r.order_line_id,b.item_id,v_take,b.unit_id,b.id);update public.inventory_batches set quantity_remaining=quantity_remaining-v_take,status=case when quantity_remaining-v_take<=0 then 'depleted' else status end,updated_at=now() where id=b.id;insert into public.inventory_transactions(item_id,batch_id,transaction_type,quantity,unit_id,occurred_at,reference_type,reference_id,reference_line_id,unit_cost,notes,created_by) values(b.item_id,b.id,'dispatch',-v_take,b.unit_id,p_dispatch_date,'dispatch',v_dispatch_id,v_line_id,b.unit_cost,'FIFO dispatch',v_user);v_need:=v_need-v_take;end loop;if v_need>0 then raise exception 'Insufficient stock for order line %; short by %',r.order_line_id,v_need;end if;update public.order_lines set dispatched_quantity=coalesce(dispatched_quantity,0)+r.quantity,reserved_quantity=greatest(0,coalesce(reserved_quantity,0)-r.quantity),updated_at=now() where id=r.order_line_id and order_id=p_order_id;end loop;update public.stock_reservations set status='consumed',consumed_at=now(),updated_at=now() where order_id=p_order_id and status='active';update public.orders set status=case when not exists(select 1 from public.order_lines where order_id=p_order_id and coalesce(dispatched_quantity,0)<ordered_quantity) then 'dispatched' else 'partially_dispatched' end,updated_at=now() where id=p_order_id;perform public.record_audit_event('dispatch.completed','dispatch',v_dispatch_id,jsonb_build_object('order_id',p_order_id),'application');return jsonb_build_object('dispatch_id',v_dispatch_id,'order_id',p_order_id,'status','dispatched');end; $$;
revoke all on function public.dispatch_order(uuid,date,text,jsonb) from public,anon;grant execute on function public.dispatch_order(uuid,date,text,jsonb) to authenticated;

create or replace function public.create_sale_invoice(p_dispatch_id uuid) returns jsonb language plpgsql security invoker set search_path = '' as $$ declare v_user uuid:=auth.uid();v_sale_id uuid:=gen_random_uuid();v_invoice_id uuid:=gen_random_uuid();v_order_id uuid;v_customer_id uuid;r record;v_subtotal numeric:=0;v_total numeric:=0;begin if v_user is null then raise exception 'Authentication required';end if;select order_id into v_order_id from public.dispatches where id=p_dispatch_id and status='dispatched';if v_order_id is null then raise exception 'Dispatch not found or not completed';end if;if exists(select 1 from public.sales where dispatch_id=p_dispatch_id) then raise exception 'Sale already exists for dispatch';end if;select customer_id into v_customer_id from public.orders where id=v_order_id;insert into public.sales(id,order_id,dispatch_id,customer_id,sale_date,created_by) values(v_sale_id,v_order_id,p_dispatch_id,v_customer_id,current_date,v_user);for r in select dl.id dispatch_line_id,dl.item_id,dl.quantity,dl.unit_id,ol.selling_rate,coalesce(ol.discount_amount,0) discount_amount,coalesce(ol.tax_amount,0) tax_amount from public.dispatch_lines dl join public.order_lines ol on ol.id=dl.order_line_id where dl.dispatch_id=p_dispatch_id loop insert into public.sale_lines(sale_id,dispatch_line_id,item_id,quantity,unit_id,selling_rate,discount_amount,tax_amount,line_total) values(v_sale_id,r.dispatch_line_id,r.item_id,r.quantity,r.unit_id,r.selling_rate,r.discount_amount,r.tax_amount,(r.quantity*r.selling_rate)-r.discount_amount+r.tax_amount);v_subtotal:=v_subtotal+(r.quantity*r.selling_rate);v_total:=v_total+((r.quantity*r.selling_rate)-r.discount_amount+r.tax_amount);end loop;update public.sales set subtotal=v_subtotal,total_amount=v_total,amount_due=v_total,status='approved',updated_at=now() where id=v_sale_id;insert into public.invoices(id,sale_id,invoice_date,billing_customer_id,subtotal,total_amount,amount_due,status,created_by) values(v_invoice_id,v_sale_id,current_date,v_customer_id,v_subtotal,v_total,v_total,'issued',v_user);for r in select sl.* from public.sale_lines sl where sl.sale_id=v_sale_id loop insert into public.invoice_lines(invoice_id,sale_line_id,item_id,quantity,unit_id,rate,discount_amount,tax_amount,line_total) values(v_invoice_id,r.id,r.item_id,r.quantity,r.unit_id,r.selling_rate,r.discount_amount,r.tax_amount,r.line_total);end loop;perform public.record_audit_event('sale.invoice.created','sale',v_sale_id,jsonb_build_object('invoice_id',v_invoice_id,'dispatch_id',p_dispatch_id),'application');return jsonb_build_object('sale_id',v_sale_id,'invoice_id',v_invoice_id,'total_amount',v_total,'amount_due',v_total);end; $$;
revoke all on function public.create_sale_invoice(uuid) from public,anon;grant execute on function public.create_sale_invoice(uuid) to authenticated;
